type deployEnv struct {
	// timeout shortens the fixed observation budget in tests.
	timeout time.Duration
	check   func(release.Qualification, string) error
	inspect func(string, string, string) (binaryReceipt, error)
	git     func(context.Context, ...string) (string, error)
	// storage returns the Object Storage client of a cell's region.
	storage func(cell string) (releasechannel.ObjectClient, error)
	// secret reads one Vault secret.
	secret   func(ctx context.Context, vaultID, name string) ([]byte, error)
	discover func(context.Context) ([]string, error)
}

func (c command) deploy(args []string) error {
	return c.deployWith(args, deployEnv{check: c.verifyGitHubQualification, inspect: c.inspectBinary, git: runGit,
		storage: operatorObjectStorage, secret: readVaultSecret, discover: discoverServingCells})
}

// deployWith signs and deploys one CI-qualified release independently in
// every cell with the online update leaf. Each cell owns
// its quorum, health gates and rollback. A failed cell fails the command
// after every other started deployment has finished.
func (c command) deployWith(args []string, env deployEnv) error {
	flags := flag.NewFlagSet("deploy", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	directory := flags.String("dir", "", "retained CI release: qualification.json and terrascale-orchestrator-linux-<arch>")
	evidenceDir := flags.String("production-evidence-dir", "", "retained signed runtime and workload evidence; default DIR/production")
	sourceRevision := flags.String("source-revision", "", "expected exact Git revision")
	delegationPath := flags.String("update-delegation", "", "root-signed binary update delegation")
	delegationSecret := flags.String("update-delegation-secret", "", "OCI Vault secret holding the root-signed release delegation, instead of --update-delegation")
	rootPath := flags.String("root-key", "", "root public key PEM")
	keyPath := flags.String("signing-key", "", "owner-only update leaf Ed25519 PKCS#8 private key PEM")
	keySecret := flags.String("signing-key-secret", "", "OCI Vault secret holding the update leaf key, instead of --signing-key")
	vaultID := flags.String("vault-id", "", "OCI Vault of --signing-key-secret and --update-delegation-secret")
	environment := flags.String("environment", "", "production or canary; default the region's admitted scope")
	checkout := flags.String("source-checkout", "", "repository checkout used to prove lineage")
	namespace := flags.String("namespace", "", "Object Storage namespace of the regions' head buckets")
	validFor := flags.Duration("valid-for", 7*24*time.Hour, "receipt validity, bounded by delegation expiry")
	poll := flags.Duration("poll", 30*time.Second, "how often a cell's status is read")
	var cells, architectures stringList
	flags.Var(&cells, "cell", "cell to deploy to concurrently; repeatable; default every serving cell")
	flags.Var(&architectures, "arch", "amd64 or arm64; repeatable; default each region's architectures")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *directory == "" || !release.ValidSourceRevision(*sourceRevision) || (*delegationPath == "") == (*delegationSecret == "") || *rootPath == "" ||
		(*keyPath == "") == (*keySecret == "") || (*keySecret == "" && *delegationSecret == "") != (*vaultID == "") ||
		*environment != "" && !validEnvironment(*environment) || *checkout == "" || !validStorageToken(*namespace) ||
		*poll <= 0 || flags.NArg() != 0 {
		return errors.New("deploy requires --dir, --source-revision, --update-delegation or --update-delegation-secret, --root-key, --signing-key or --signing-key-secret, --vault-id with any secret, --source-checkout and --namespace")
	}
	targetCells, err := deploymentCells(c.ctx, cells, env.discover)
	if err != nil {
		return err
	}
	cells = targetCells
	for _, architecture := range architectures {
		if architecture != "amd64" && architecture != "arm64" {
			return fmt.Errorf("unsupported architecture %q", architecture)
		}
	}
	qualification, qualificationDigest, err := readQualification(filepath.Join(*directory, "qualification.json"))
	if err != nil {
		return err
	}
	if qualification.SourceRevision != *sourceRevision {
		return errors.New("qualification names another source revision")
	}
	if err := env.check(qualification, qualificationDigest); err != nil {
		return err
	}
	root, err := readRootPublicKey(*rootPath)
	if err != nil {
		return err
	}
	roots, err := trust.ParseKeyring(root)
	if err != nil {
		return err
	}
	if *evidenceDir == "" {
		*evidenceDir = filepath.Join(*directory, "production")
	}
	regionTimeout := rollout.ObservationBudget
	if env.timeout > 0 {
		regionTimeout = min(regionTimeout, env.timeout)
	}
	progress := &deploymentWriter{Writer: c.output}
	type signingCredentials struct {
		delegation trust.Envelope
		private    ed25519.PrivateKey
	}
	credentials := sync.OnceValues(func() (signingCredentials, error) {
		var delegation trust.Envelope
		var err error
		if *delegationPath != "" {
			delegation, err = readEnvelope(*delegationPath)
		} else {
			var data []byte
			if data, err = env.secret(c.ctx, *vaultID, *delegationSecret); err == nil {
				delegation, err = trust.DecodeEnvelope(data)
			}
		}
		if err != nil {
			return signingCredentials{}, fmt.Errorf("read the update delegation: %w", err)
		}
		var private ed25519.PrivateKey
		if *keyPath != "" {
			private, err = readDelegatedPrivateKey(*keyPath)
		} else {
			var data []byte
			if data, err = env.secret(c.ctx, *vaultID, *keySecret); err == nil {
				private, err = parseDelegatedPrivateKey(data)
				clear(data)
			}
		}
		if err != nil {
			return signingCredentials{}, fmt.Errorf("read the update leaf key: %w", err)
		}
		return signingCredentials{delegation, private}, nil
	})
	var private ed25519.PrivateKey
	defer func() { clear(private) }()

	started := time.Now()
	lineage := &deploymentLineage{checker: gitLineage{ctx: c.ctx, checkout: *checkout, run: env.git},
		results: make(map[[3]string]error)}
	var regions errgroup.Group
	regions.SetLimit(4)
	var failureMu sync.Mutex
	var failures []error
	preflights := c.prepareDeploymentTargets(*directory, *evidenceDir, *namespace, *environment,
		cells, architectures, qualification, qualificationDigest, roots, regionTimeout, env, progress)
	for result := range preflights {
		if result.err != nil {
			failureMu.Lock()
			failures = append(failures, result.err)
			failureMu.Unlock()
			continue
		}
		target := result.target
		regions.Go(func() (regionErr error) {
			ctx, cancel := context.WithTimeout(c.ctx, regionTimeout)
			defer cancel()
			regional := c
			regional.ctx = ctx
			deadline := time.Now().UTC().Add(regionTimeout)
			cell := target.cell
			defer func() {
				if regionErr != nil {
					failureMu.Lock()
					failures = append(failures, fmt.Errorf("%s: %w", cell, regionErr))
					failureMu.Unlock()
					fmt.Fprintf(progress, "%s failed: %v\n", cell, regionErr)
				}
			}()
			cellStarted := time.Now()
			location, cellEnvironment, cellArchitectures, binaries := target.location, target.environment, target.architectures, target.binaries
			if err := regional.verifyProductionArtifacts(*evidenceDir, roots, cell, cellEnvironment, binaries, deadline); err != nil {
				return err
			}
			keys, err := credentials()
			if err != nil {
				return err
			}
			failureMu.Lock()
			private = keys.private
			failureMu.Unlock()
			delegationWire, err := trust.EncodeEnvelope(keys.delegation)
			if err != nil {
				return err
			}
			channel := releasechannel.Channel{Schema: releasechannel.ChannelSchema, Cell: cell, Environment: cellEnvironment,
				SourceRevision: *sourceRevision, RunNumber: qualification.Verification.RunNumber, Delegation: delegationWire}
			for _, architecture := range cellArchitectures {
				envelope, err := release.SignBinaryUpdateReceipt(binaries[architecture], qualification, qualificationDigest, cell,
					cellEnvironment, lineage, keys.delegation, roots, keys.private, cellStarted.UTC(), *validFor)
				if err != nil {
					return fmt.Errorf("sign %s: %w", architecture, err)
				}
				proof, err := readProductionProof(*evidenceDir, cell, architecture)
				if err != nil {
					return err
				}
				envelope, err = release.AttachProductionQualification(envelope, proof, delegationWire, roots, keys.private,
					release.UpdateExpectation{Environment: cellEnvironment, Cell: cell, Architecture: architecture}, cellStarted.UTC())
				if err != nil {
					return err
				}
				wire, err := trust.EncodeEnvelope(envelope)
				if err != nil {
					return err
				}
				channel.Receipts = append(channel.Receipts, wire)
			}
			// Receipts must remain valid through the shared rollout deadline.
			if _, err := channel.Verify(roots, cell, cellEnvironment, deadline); err != nil {
				return fmt.Errorf("receipts would expire during rollout; renew the update delegation: %w", err)
			}
			for _, architecture := range cellArchitectures {
				if err := regional.uploadBinary(location, binaryPath(*directory, architecture), binaries[architecture].SHA256); err != nil {
					return fmt.Errorf("upload the %s binary to %s: %w", architecture, channel.Cell, err)
				}
			}
			if err := releasechannel.Publish(ctx, location, channel); err != nil {
				return fmt.Errorf("publish to %s: %w", channel.Cell, err)
			}
			fmt.Fprintf(progress, "%s published: run %d %s\n", channel.Cell, channel.RunNumber, channel.SourceRevision)
			if err := releasechannel.Await(ctx, location, channel, *poll, deadline, progress); err != nil {
				return err
			}
			fmt.Fprintf(progress, "%s rolled out in %s\n", channel.Cell, time.Since(cellStarted).Round(time.Second))
			return nil
		})
	}
	// Do not cancel a healthy cell's rollout when another cell rolls back.
	_ = regions.Wait()
	if err := errors.Join(failures...); err != nil {
		return fmt.Errorf("fleet rollout failed: %w", err)
	}
	_, err = fmt.Fprintf(c.output, "fleet complete: run %d %s in %s after %s\n", qualification.Verification.RunNumber,
		*sourceRevision, strings.Join(cells, " "), time.Since(started).Round(time.Second))
	return err
}

// Share each lineage proof and serialize fetches so parallel signers cannot
// race Git's ref locks or repeat the same network request per architecture.
type deploymentLineage struct {
	sync.Mutex
	checker release.LineageChecker
	results map[[3]string]error
}

func (lineage *deploymentLineage) CheckLineage(base, revision, ref string) error {
	lineage.Lock()
	defer lineage.Unlock()
	key := [3]string{base, revision, ref}
	if err, found := lineage.results[key]; found {
		return err
	}
	err := lineage.checker.CheckLineage(base, revision, ref)
	lineage.results[key] = err
	return err
}

// deploymentWriter serializes progress from independent regional waits.
type deploymentWriter struct {
	sync.Mutex
	io.Writer
}

func (writer *deploymentWriter) Write(data []byte) (int, error) {
	writer.Lock()
	defer writer.Unlock()
	return writer.Writer.Write(data)
}

func binaryPath(directory, architecture string) string {
	return filepath.Join(directory, "terrascale-orchestrator-linux-"+architecture)
}

// uploadBinary stores the binary under its digest unless the bucket already
// holds exactly those bytes.
func (c command) uploadBinary(location releasechannel.Location, path, sha256 string) error {
	file, size, digest, err := c.openHashedArtifact(path, maxArtifactBytes)
	if err != nil {
		return err
	}
	defer file.Close()
	if hex.EncodeToString(digest) != sha256 {
		return errors.New("binary changed after it was inspected")
	}
	return putImmutable(c.ctx, location.Client, location.Namespace, location.Bucket,
		releasechannel.BinaryObject(sha256), file, size, digest)
}

func channelLocation(env deployEnv, cell, namespace string) (releasechannel.Location, error) {
	bucket, err := releasechannel.BucketName(cell)
	if err != nil {
		return releasechannel.Location{}, err
	}
	client, err := env.storage(cell)
	if err != nil {
		return releasechannel.Location{}, err
	}
	return releasechannel.Location{Client: client, Namespace: namespace, Bucket: bucket}, nil
}

package cli

import (
	"context"
	"fmt"
	"io"
	"sync"
	"time"

	"golang.org/x/sync/errgroup"

	"github.com/TerraScale/ts-orchestrator/internal/release"
	"github.com/TerraScale/ts-orchestrator/internal/releasechannel"
	"github.com/TerraScale/ts-orchestrator/internal/trust"
)

type deploymentTarget struct {
	cell          string
	environment   string
	architectures []string
	binaries      map[string]binaryReceipt
	location      releasechannel.Location
}

// Admit independently before retrieving any signing credentials.
func (c command) prepareDeploymentTargets(directory, evidenceDir, namespace, environment string,
	cells, architectures []string, qualification release.Qualification, qualificationDigest string,
	roots trust.Keyring, budget time.Duration, env deployEnv, progress io.Writer,
) <-chan deploymentPreflightResult {
	results := make(chan deploymentPreflightResult)
	go func() {
		defer close(results)
		inspected := make(map[string]binaryReceipt)
		var inspection sync.Mutex
		var regions errgroup.Group
		regions.SetLimit(4)
		for _, cell := range cells {
			regions.Go(func() error {
				ctx, cancel := context.WithTimeout(c.ctx, budget)
				defer cancel()
				regional := c
				regional.ctx = ctx
				target := deploymentTarget{cell: cell, environment: environment, architectures: architectures}
				admit := func() error {
					if target.environment == "" || len(target.architectures) == 0 {
						location, err := channelLocation(env, cell, namespace)
						if err != nil {
							return err
						}
						scope, err := deploymentScope(ctx, location, cell)
						if err != nil {
							return err
						}
						if target.environment == "" {
							target.environment = scope.Environment
						}
						if len(target.architectures) == 0 {
							target.architectures = scope.Architectures
						}
						target.location = location
					}
					target.binaries = make(map[string]binaryReceipt, len(target.architectures))
					for _, architecture := range target.architectures {
						inspection.Lock()
						receipt, found := inspected[architecture]
						var err error
						if !found {
							receipt, err = env.inspect(binaryPath(directory, architecture), qualification.GoVersion, qualification.SourceRevision)
							if err == nil {
								inspected[architecture] = receipt
							}
						}
						inspection.Unlock()
						if err != nil {
							return err
						}
						receipt.QualificationSHA256 = qualificationDigest
						if err := qualification.MatchBinary(receipt, qualificationDigest); err != nil {
							return err
						}
						if receipt.GOARCH != architecture {
							return fmt.Errorf("%s binary is built for %s", architecture, receipt.GOARCH)
						}
						target.binaries[architecture] = receipt
					}
					if err := regional.verifyProductionArtifacts(evidenceDir, roots, cell, target.environment, target.binaries, time.Now().UTC().Add(budget)); err != nil {
						return err
					}
					if target.location.Client == nil {
						location, err := channelLocation(env, cell, namespace)
						if err != nil {
							return err
						}
						target.location = location
					}
					return nil
				}
				err := admit()
				if err != nil {
					err = fmt.Errorf("%s: %w", cell, err)
					fmt.Fprintf(progress, "%s qualification refused: %v\n", cell, err)
				}
				select {
				case results <- deploymentPreflightResult{target, err}:
				case <-c.ctx.Done():
				}
				return nil
			})
		}
		_ = regions.Wait()
	}()
	return results
}

type deploymentPreflightResult struct {
	target deploymentTarget
	err    error
}

func (c command) verifyProductionArtifacts(evidenceDir string, roots trust.Keyring, cell, environment string, binaries map[string]binaryReceipt, now time.Time) error {
	if len(binaries) == 0 {
		return fmt.Errorf("%w: no candidate artifacts", release.ErrProductionQualification)
	}
	for architecture, binary := range binaries {
		if err := binary.Validate(); err != nil {
			return fmt.Errorf("%w: %w", release.ErrProductionQualification, err)
		}
		if binary.GOARCH != architecture {
			return fmt.Errorf("%w: artifact architecture", release.ErrProductionQualification)
		}
		expected := release.ProductionExpectation{SourceRevision: binary.SourceRevision, ArtifactSHA256: binary.SHA256,
			QualificationSHA256: binary.QualificationSHA256, Cell: cell, Environment: environment,
			Runtime: release.ProductionRuntime, Architecture: architecture, Role: "orchestrator"}
		if err := c.verifyProductionCandidate(evidenceDir, roots, expected, now); err != nil {
			return err
		}
	}
	return c.ctx.Err()
}

// verifyProductionCandidate consumes only signed qualification and retained bytes.
func (c command) verifyProductionCandidate(evidenceDir string, roots trust.Keyring, expected release.ProductionExpectation, now time.Time) error {
	directory := filepath.Join(evidenceDir, expected.Cell, expected.Architecture)
	wire, err := readBoundedRegular(filepath.Join(directory, "production.json"), trust.MaxEnvelopeBytes)
	if err != nil {
		return fmt.Errorf("%w: %s %s record: %w", release.ErrProductionQualification, expected.Cell, expected.Architecture, err)
	}
	delegation, err := readBoundedRegular(filepath.Join(directory, "delegation.json"), trust.MaxEnvelopeBytes)
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("%w: qualification delegation: %w", release.ErrProductionQualification, err)
	}
	if _, err := release.VerifyProductionCurrent(wire, delegation, roots, expected, time.Now().UTC()); err != nil {
		return fmt.Errorf("%s %s current admission: %w", expected.Cell, expected.Architecture, err)
	}
	qualification, err := release.VerifyProductionCurrent(wire, delegation, roots, expected, now)
	if err != nil {
		return fmt.Errorf("%s %s: %w", expected.Cell, expected.Architecture, err)
	}
	for _, evidence := range qualification.Evidence {
		file, err := openRegular(filepath.Join(evidenceDir, "objects", evidence.SHA256))
		if err != nil {
			return fmt.Errorf("%w: %s %s evidence: %w", release.ErrProductionQualification, expected.Cell, evidence.Gate, err)
		}
		if err := errors.Join(release.VerifyProductionEvidence(c.ctx, file, evidence, expected), file.Close()); err != nil {
			return fmt.Errorf("%s %s retained evidence: %w", expected.Cell, evidence.Gate, err)
		}
	}
	return c.ctx.Err()
}

func readProductionProof(evidenceDir, cell, architecture string) (release.ProductionProof, error) {
	directory := filepath.Join(evidenceDir, cell, architecture)
	wire, err := readBoundedRegular(filepath.Join(directory, "production.json"), trust.MaxEnvelopeBytes)
	if err != nil {
		return release.ProductionProof{}, err
	}
	delegation, err := readBoundedRegular(filepath.Join(directory, "delegation.json"), trust.MaxEnvelopeBytes)
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return release.ProductionProof{}, err
	}
	return release.ProductionProof{Qualification: wire, Delegation: delegation}, nil
}

func ProductionQualificationScope(candidate ProductionExpectation) trust.Scope {
	return trust.Scope{Domain: ProductionQualificationDomain, DeploymentID: entityid.Derive("build", candidate.SourceRevision),
		Cell: candidate.Cell, Environment: candidate.Environment, Role: candidate.Role,
		Slot: candidate.Runtime + "/linux-" + candidate.Architecture}
}

// VerifyProductionCurrent accepts a trusted root or an explicitly delegated
// qualification signer. An ordinary binary-release delegation grants no authority.
// The caller must also verify the referenced retained evidence bytes.
func VerifyProductionCurrent(wire, delegationWire []byte, roots trust.Keyring, expected ProductionExpectation, now time.Time) (ProductionQualification, error) {
	var qualification ProductionQualification
	gates := []string{"runtime-ha", "workload-safety"}
	schema := ProductionQualificationSchema
	if expected.Role == FoundationWriterRole {
		schema = FoundationWriterQualificationSchema
		gates = append(gates, RootCredentialBoundaryGate)
	}
	validRuntime := expected.Runtime == ProductionRuntime
	if expected.Role == FoundationWriterRole {
		validRuntime = validRuntime && ValidOCIImageIDForRegion(expected.ImageOCID, expected.Cell)
	}
	if expected.Role == "netbird-manager" || expected.Runtime == NetBirdProductionRuntime {
		validRuntime = expected.Role == "netbird-manager" && expected.Runtime == NetBirdProductionRuntime &&
			expected.Cell == "GRU" && expected.Architecture == "arm64"
		gates = []string{"netbird-foundation", "netbird-recovery"}
	}
	if !ValidSourceRevision(expected.SourceRevision) || !digestPattern.MatchString(expected.ArtifactSHA256) ||
		!digestPattern.MatchString(expected.QualificationSHA256) || !ValidRegion(expected.Cell) ||
		!ValidEnvironment(expected.Environment) || !validRuntime ||
		expected.Architecture != "amd64" && expected.Architecture != "arm64" || !serviceRolePattern.MatchString(expected.Role) {
		return qualification, fmt.Errorf("%w: candidate scope", ErrProductionQualification)
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	policy := trust.Policy{MaxLifetime: MaxUpdateReceiptLifetime}
	var payload []byte
	if len(delegationWire) == 0 {
		payload, err = trust.VerifyCurrent(envelope, ProductionQualificationScope(expected), roots, now, policy)
	} else {
		var delegationEnvelope trust.Envelope
		delegationEnvelope, err = trust.DecodeEnvelope(delegationWire)
		if err == nil {
			var delegation trust.VerifiedDelegation
			delegation, err = trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, policy)
			if err == nil {
				payload, err = trust.VerifyDelegatedCurrent(envelope, ProductionQualificationScope(expected), delegation, now, policy)
			}
		}
	}
	if err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	if err := protocol.DecodeStrict(payload, &qualification, trust.MaxPayloadBytes); err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	if qualification.Schema != schema || qualification.Candidate != expected || len(qualification.Evidence) != len(gates) {
		return qualification, fmt.Errorf("%w: candidate or required gates", ErrProductionQualification)
	}
	for index, gate := range gates {
		evidence := qualification.Evidence[index]
		if evidence.Gate != gate || !digestPattern.MatchString(evidence.SHA256) ||
			evidence.Bytes <= 0 || evidence.Bytes > MaxProductionEvidenceBytes || evidence.CompletedAt.IsZero() ||
			evidence.CompletedAt.After(envelope.IssuedAt) {
			return qualification, fmt.Errorf("%w: %s evidence", ErrProductionQualification, gate)
		}
	}
	return qualification, nil
}

// VerifyProductionEvidence checks bytes against authenticated gate metadata.
// The privileged gate additionally requires the exact native boundary observations.
func VerifyProductionEvidence(ctx context.Context, reader io.Reader, evidence ProductionGateEvidence, expected ProductionExpectation) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if reader == nil || evidence.Bytes <= 0 || evidence.Bytes > MaxProductionEvidenceBytes || !digestPattern.MatchString(evidence.SHA256) {
		return fmt.Errorf("%w: retained %s evidence metadata", ErrProductionQualification, evidence.Gate)
	}
	digest := sha256.New()
	var body bytes.Buffer
	var destination io.Writer = digest
	if evidence.Gate == RootCredentialBoundaryGate {
		destination = io.MultiWriter(digest, &body)
	}
	count, err := io.Copy(destination, io.LimitReader(reader, evidence.Bytes+1))
	if err != nil {
		return fmt.Errorf("read retained %s evidence: %w", evidence.Gate, err)
	}
	if count != evidence.Bytes || hex.EncodeToString(digest.Sum(nil)) != evidence.SHA256 {
		return fmt.Errorf("%w: retained %s evidence differs from the signed size or SHA-256", ErrProductionQualification, evidence.Gate)
	}
	if evidence.Gate == RootCredentialBoundaryGate {
		var boundary RootCredentialBoundaryEvidence
		if err := protocol.DecodeStrict(body.Bytes(), &boundary, MaxProductionEvidenceBytes); err != nil {
			return fmt.Errorf("%w: root credential boundary evidence: %w", ErrProductionQualification, err)
		}
		if err := boundary.Validate(expected); err != nil {
			return err
		}
		if !boundary.CompletedAt.Equal(evidence.CompletedAt) {
			return fmt.Errorf("%w: root credential boundary completion time", ErrProductionQualification)
		}
	}
	return ctx.Err()
}

func putImmutable(ctx context.Context, client immutableObjectClient, namespace, bucket, name string, source io.ReadSeeker, size int64, digest []byte) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if size <= 0 || size > maxArtifactBytes || len(digest) != sha256.Size {
		return errors.New("immutable object size or SHA-256 digest is invalid")
	}
	if _, err := source.Seek(0, io.SeekStart); err != nil {
		return fmt.Errorf("rewind release asset: %w", err)
	}
	noOverwrite := "*"
	contentType := "application/octet-stream"
	cacheControl := "public, max-age=31536000, immutable"
	checksum := base64.StdEncoding.EncodeToString(digest)
	if err := ctx.Err(); err != nil {
		return err
	}
	_, putErr := client.PutObject(ctx, objectstorage.PutObjectRequest{
		NamespaceName: common.String(namespace), BucketName: common.String(bucket), ObjectName: common.String(name),
		ContentLength: common.Int64(size), PutObjectBody: io.NopCloser(&boundedReadSeeker{source: source, size: size}),
		IfNoneMatch: common.String(noOverwrite), ContentType: common.String(contentType), CacheControl: common.String(cacheControl),
		OpcChecksumAlgorithm: objectstorage.PutObjectOpcChecksumAlgorithmSha256, OpcContentSha256: common.String(checksum),
	})
	getErr := getExactObjectDigest(ctx, client, namespace, bucket, name, size, digest)
	if getErr != nil {
		if putErr != nil {
			return errors.Join(fmt.Errorf("create immutable release object: %w", putErr), fmt.Errorf("read back release object: %w", getErr))
		}
		return fmt.Errorf("release object upload succeeded but exact read-back failed: %w", getErr)
	}
	if putErr != nil {
		// Conditional create may lose an acknowledgement or find an identical
		// earlier publication. Exact read-back proves this immutable receipt.
		return nil
	}
	return nil
}

type boundedReadSeeker struct {
	source io.ReadSeeker
	size   int64
}

func (reader *boundedReadSeeker) Read(contents []byte) (int, error) {
	position, err := reader.source.Seek(0, io.SeekCurrent)
	if err != nil {
		return 0, err
	}
	if position < 0 || position >= reader.size {
		return 0, io.EOF
	}
	if remaining := reader.size - position; int64(len(contents)) > remaining {
		contents = contents[:remaining]
	}
	return reader.source.Read(contents)
}

func (reader *boundedReadSeeker) Seek(offset int64, whence int) (int64, error) {
	current, err := reader.source.Seek(0, io.SeekCurrent)
	if err != nil {
		return current, err
	}
	var position int64
	switch whence {
	case io.SeekStart:
		position = offset
	case io.SeekCurrent:
		if offset < -current || offset > reader.size-current {
			return current, errors.New("seek is outside the bounded release asset")
		}
		position = current + offset
	case io.SeekEnd:
		if offset < -reader.size || offset > 0 {
			return current, errors.New("seek is outside the bounded release asset")
		}
		position = reader.size + offset
	default:
		return current, errors.New("invalid release asset seek origin")
	}
	if position < 0 || position > reader.size {
		return current, errors.New("seek is outside the bounded release asset")
	}
	return reader.source.Seek(position, io.SeekStart)
}

func getExactObjectDigest(ctx context.Context, client immutableObjectClient, namespace, bucket, name string, expectedBytes int64, expectedDigest []byte) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	response, err := ociclient.ReadObject(ctx, client, objectstorage.GetObjectRequest{
		NamespaceName: common.String(namespace), BucketName: common.String(bucket), ObjectName: common.String(name),
	})
	if err != nil {
		return err
	}
	defer response.Content.Close()
	if response.ContentLength != nil && *response.ContentLength != expectedBytes {
		return fmt.Errorf("stored object length %d does not match %d", *response.ContentLength, expectedBytes)
	}
	hash := sha256.New()
	read, err := io.Copy(hash, commandio.Reader(ctx, io.LimitReader(response.Content, expectedBytes+1)))
	if err != nil {
		return err
	}
	if read != expectedBytes {
		return fmt.Errorf("stored object read %d bytes, expected %d", read, expectedBytes)
	}
	if !bytes.Equal(hash.Sum(nil), expectedDigest) {
		return errors.New("release object name already contains different bytes; refusing overwrite")
	}
	return nil
}

type objectReader interface {
	GetObject(context.Context, objectstorage.GetObjectRequest) (objectstorage.GetObjectResponse, error)
}

// ReadObject joins SDK retry work while retaining cancellation at the HTTP boundary.
// Other implementations receive the original context and own their cancellation.
func ReadObject(ctx context.Context, client objectReader, request objectstorage.GetObjectRequest) (objectstorage.GetObjectResponse, error) {
	switch sdk := client.(type) {
	case objectstorage.ObjectStorageClient:
		ConfigureReadCancellation(&sdk.BaseClient)
		return sdk.GetObject(ReadContext(ctx), request)
	case *objectstorage.ObjectStorageClient:
		copy := *sdk
		ConfigureReadCancellation(&copy.BaseClient)
		return copy.GetObject(ReadContext(ctx), request)
	default:
		return client.GetObject(ctx, request)
	}
}

// Publish CAS-publishes an already verified channel. Migrated channels use
// signer-owned sequence order; legacy channels retain their historical run floor.
// A malformed current channel stops publication for inspection.
func Publish(ctx context.Context, location Location, channel Channel) error {
	wire, err := json.Marshal(channel, json.Deterministic(true))
	if err != nil {
		return err
	}
	for range 3 {
		current, etag, found, err := location.get(ctx, ChannelObject, MaxChannelBytes)
		if err != nil {
			return err
		}
		if found {
			var existing Channel
			if err := json.Unmarshal(current, &existing); err != nil {
				return fmt.Errorf("decode the current release channel: %w", err)
			}
			if err := compareChannelOrder(existing, channel); err != nil {
				return err
			}
		}
		if err := location.put(ctx, ChannelObject, wire, etag); !errors.Is(err, ErrConflict) {
			return err
		}
	}
	return ErrConflict
}

// ReadChannel returns the region's channel; found is false when it has none.
func ReadChannel(ctx context.Context, location Location) (Channel, bool, error) {
	var channel Channel
	found, err := location.read(ctx, ChannelObject, MaxChannelBytes, &channel)
	return channel, found, err
}

// ReadStatus returns the region's status; found is false when it has none.
// Unknown fields are ignored: a region may run an older or newer binary.
func ReadStatus(ctx context.Context, location Location) (Status, bool, error) {
	var status Status
	found, err := location.read(ctx, StatusObject, maxStatusBytes, &status)
	return status, found, err
}

// Await polls the region's status every poll until it reports channel's
// release complete. It fails when the region reports the release failed or
// moved past it, or when deadline passes. Each status change is written to
// progress.
func Await(ctx context.Context, location Location, channel Channel, poll time.Duration, deadline time.Time,
	progress io.Writer,
) error {
	var last string
	for {
		status, found, err := ReadStatus(ctx, location)
		line := "waiting for the region to report"
		switch {
		case err != nil:
			line = "status read failed: " + err.Error()
		case !found || channel.ReleaseSequence > 0 && status.ReleaseSequence < channel.ReleaseSequence || channel.ReleaseSequence == 0 && status.ReleaseSequence == 0 && status.RunNumber < channel.RunNumber:
		case status.ReleaseSequence > channel.ReleaseSequence || channel.ReleaseSequence == 0 && status.RunNumber > channel.RunNumber:
			return fmt.Errorf("%w: %s moved on to run %d", ErrFailed, channel.Cell, status.RunNumber)
		case status.Cell != channel.Cell || status.SourceRevision != channel.SourceRevision:
			return fmt.Errorf("%w: %s reports run %d for %s %s", ErrFailed, channel.Cell, status.RunNumber,
				Clip(status.Cell), Clip(status.SourceRevision))
		case status.State == StateComplete:
			fmt.Fprintf(progress, "%s complete: run %d %s\n", channel.Cell, channel.RunNumber, channel.SourceRevision)
			return nil
		case status.State == StateFailed:
			return fmt.Errorf("%w: %s rolled back run %d: %s", ErrFailed, channel.Cell, channel.RunNumber, Clip(status.Reason))
		default:
			line = Clip(string(status.State) + " " + status.Reason)
		}
		if line != last {
			fmt.Fprintf(progress, "%s %s\n", channel.Cell, line)
			last = line
		}
		if !time.Now().Before(deadline) {
			return fmt.Errorf("%w: %s did not complete run %d in time (%s)", ErrFailed, channel.Cell, channel.RunNumber, line)
		}
		select {
		case <-ctx.Done():
			if !time.Now().Before(deadline) {
				return fmt.Errorf("%w: %s did not complete run %d in time (%s)", ErrFailed, channel.Cell, channel.RunNumber, line)
			}
			return ctx.Err()
		case <-time.After(min(poll, time.Until(deadline))):
		}
	}
}

func (location Location) read(ctx context.Context, name string, limit int64, value any) (bool, error) {
	data, _, found, err := location.get(ctx, name, limit)
	if err != nil || !found {
		return found, err
	}
	if err := json.Unmarshal(data, value); err != nil {
		return true, fmt.Errorf("%w: decode %s: %w", ErrInvalid, name, err)
	}
	return true, nil
}

func (location Location) get(ctx context.Context, name string, limit int64) ([]byte, string, bool, error) {
	response, err := ociclient.ReadObject(ctx, location.Client, objectstorage.GetObjectRequest{
		NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name,
	})
	if httpStatus(err) == http.StatusNotFound {
		return nil, "", false, nil
	}
	if err != nil {
		return nil, "", false, fmt.Errorf("read %s/%s: %w", location.Bucket, name, err)
	}
	defer response.Content.Close()
	data, err := io.ReadAll(io.LimitReader(response.Content, limit+1))
	if err != nil {
		return nil, "", false, fmt.Errorf("read %s/%s: %w", location.Bucket, name, err)
	}
	if int64(len(data)) > limit {
		return nil, "", false, fmt.Errorf("%w: %s/%s exceeds %d bytes", ErrInvalid, location.Bucket, name, limit)
	}
	if response.ETag == nil || *response.ETag == "" {
		return nil, "", false, fmt.Errorf("read %s/%s: no ETag", location.Bucket, name)
	}
	return data, *response.ETag, true, nil
}

// put writes data only if the object still has etag, or does not exist when
// etag is empty.
func (location Location) put(ctx context.Context, name string, data []byte, etag string) error {
	request := objectstorage.PutObjectRequest{
		NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name,
		ContentLength: new(int64(len(data))), PutObjectBody: io.NopCloser(bytes.NewReader(data)),
		ContentType: new("application/json"),
	}
	if etag == "" {
		request.IfNoneMatch = new("*")
	} else {
		request.IfMatch = &etag
	}
	_, err := location.Client.PutObject(ctx, request)
	if httpStatus(err) == http.StatusPreconditionFailed {
		return ErrConflict
	}
	if err != nil {
		return fmt.Errorf("write %s/%s: %w", location.Bucket, name, err)
	}
	return nil
}

