func (c command) fleetStatusWith(args []string, env deployEnv) error {
	flags := flag.NewFlagSet("fleet-status", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	namespace := flags.String("namespace", "", "Object Storage namespace of the regions' head buckets")
	requirePins := flags.Bool("require-pins", false, "refuse missing statuses or release pins before CI pruning")
	var cells stringList
	flags.Var(&cells, "cell", "cell to show; repeatable; default every cell")
	var roles stringList
	flags.Var(&roles, "role", "service role whose status to show instead of the orchestrator channel; repeatable")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if !validStorageToken(*namespace) || flags.NArg() != 0 {
		return errors.New("fleet-status requires --namespace")
	}
	for _, role := range roles {
		if !validStorageToken(role) {
			return fmt.Errorf("invalid --role %q", role)
		}
	}
	targetCells, err := deploymentCells(c.ctx, cells, env.discover)
	if err != nil {
		return err
	}
	cells = targetCells
	type line struct {
		Cell    string                 `json:"cell"`
		Channel *channelSummary        `json:"channel,omitempty"`
		Status  *releasechannel.Status `json:"status,omitempty"`
		// Services are the --role statuses, in flag order.
		Services []releasechannel.ServiceStatus `json:"services,omitempty"`
		Error    string                         `json:"error,omitempty"`
	}
	var failed []string
	for _, cell := range cells {
		out := line{Cell: cell}
		err := func() error {
			location, err := channelLocation(env, cell, *namespace)
			if err != nil {
				return err
			}
			for _, role := range roles {
				status, found, err := releasechannel.ReadServiceStatus(c.ctx, location, role)
				if err != nil {
					return err
				}
				if found {
					out.Services = append(out.Services, status)
				}
				if *requirePins && (!found || status.Schema != releasechannel.ServiceStatusSchema || status.Cell != cell ||
					status.Role != role || status.Pins == nil) {
					return fmt.Errorf("%s %s has no release pins from its leader", cell, role)
				}
				if *requirePins {
					if err := status.Pins.ValidateFresh(status.UpdatedAt, time.Now().UTC()); err != nil {
						return err
					}
				}
			}
			if len(roles) > 0 {
				return nil
			}
			channel, found, err := releasechannel.ReadChannel(c.ctx, location)
			if err != nil {
				return err
			}
			if found {
				out.Channel = &channelSummary{SourceRevision: channel.SourceRevision, RunNumber: channel.RunNumber}
			}
			status, found, err := releasechannel.ReadStatus(c.ctx, location)
			if found {
				out.Status = &status
			}
			if err == nil && *requirePins && (!found || status.Schema != releasechannel.StatusSchema || status.Cell != cell || status.Pins == nil) {
				return fmt.Errorf("%s has no release pins from its leader", cell)
			}
			if err == nil && *requirePins {
				return status.Pins.ValidateFresh(status.UpdatedAt, time.Now().UTC())
			}
			return err
		}()
		if err != nil {
			out.Error = err.Error()
			failed = append(failed, cell)
		}
		if err := json.MarshalWrite(c.output, out); err != nil {
			return err
		}
		if _, err := io.WriteString(c.output, "\n"); err != nil {
			return err
		}
	}
	if len(failed) > 0 {
		return fmt.Errorf("could not read the release status of %s", strings.Join(failed, " "))
	}
	return nil
}

// Validate refuses an absent inventory or digests the pruning script would
// silently skip. Status comes from a remote bucket, not trusted cell state.
func (pins *ReleasePins) Validate() error {
	if pins == nil {
		return fmt.Errorf("%w: release pins are missing", ErrInvalid)
	}
	for _, digests := range [][]string{pins.Rollback, pins.KnownBad} {
		for _, digest := range digests {
			if _, err := hex.DecodeString(digest); err != nil || len(digest) != 64 || strings.ToLower(digest) != digest {
				return fmt.Errorf("%w: release pin %q", ErrInvalid, digest)
			}
		}
	}
	return nil

// ReadChannel returns the region's channel; found is false when it has none.
func ReadChannel(ctx context.Context, location Location) (Channel, bool, error) {
	var channel Channel
	found, err := location.read(ctx, ChannelObject, MaxChannelBytes, &channel)
	return channel, found, err
}

// ReadStatus returns the region's status; found is false when it has none.
// Unknown fields are ignored: a region may run an older or newer binary.
func ReadStatus(ctx context.Context, location Location) (Status, bool, error) {
	var status Status
	found, err := location.read(ctx, StatusObject, maxStatusBytes, &status)
	return status, found, err
}

func (location Location) read(ctx context.Context, name string, limit int64, value any) (bool, error) {
	data, _, found, err := location.get(ctx, name, limit)
	if err != nil || !found {
		return found, err
	}
	if err := json.Unmarshal(data, value); err != nil {
		return true, fmt.Errorf("%w: decode %s: %w", ErrInvalid, name, err)
	}
	return true, nil
}

func (location Location) get(ctx context.Context, name string, limit int64) ([]byte, string, bool, error) {
	response, err := ociclient.ReadObject(ctx, location.Client, objectstorage.GetObjectRequest{
		NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name,
	})
	if httpStatus(err) == http.StatusNotFound {
		return nil, "", false, nil
	}
	if err != nil {
		return nil, "", false, fmt.Errorf("read %s/%s: %w", location.Bucket, name, err)
	}
	defer response.Content.Close()
	data, err := io.ReadAll(io.LimitReader(response.Content, limit+1))
	if err != nil {
		return nil, "", false, fmt.Errorf("read %s/%s: %w", location.Bucket, name, err)
	}
	if int64(len(data)) > limit {
		return nil, "", false, fmt.Errorf("%w: %s/%s exceeds %d bytes", ErrInvalid, location.Bucket, name, limit)
	}
	if response.ETag == nil || *response.ETag == "" {
		return nil, "", false, fmt.Errorf("read %s/%s: no ETag", location.Bucket, name)
	}
	return data, *response.ETag, true, nil
}

// put writes data only if the object still has etag, or does not exist when
// etag is empty.
func (location Location) put(ctx context.Context, name string, data []byte, etag string) error {
	request := objectstorage.PutObjectRequest{
		NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name,
		ContentLength: new(int64(len(data))), PutObjectBody: io.NopCloser(bytes.NewReader(data)),
		ContentType: new("application/json"),
	}
	if etag == "" {
		request.IfNoneMatch = new("*")
	} else {
		request.IfMatch = &etag
	}
	_, err := location.Client.PutObject(ctx, request)
	if httpStatus(err) == http.StatusPreconditionFailed {
		return ErrConflict
	}
	if err != nil {
		return fmt.Errorf("write %s/%s: %w", location.Bucket, name, err)
	}
	return nil
}

// ReadServiceStatus returns role's status; found is false when it has none.
func ReadServiceStatus(ctx context.Context, location Location, role string) (ServiceStatus, bool, error) {
	var status ServiceStatus
	found, err := location.read(ctx, ServiceStatusObject(role), maxStatusBytes, &status)
	return status, found, err
}

// PinRefreshInterval keeps inventories current; MaxPinAge bounds how long
// pruning can use one when collection or publication stops succeeding.
const (
	PinRefreshInterval = 30 * time.Second
	MaxPinAge          = 2 * time.Minute
)

// PinRefreshDue also corrects timestamps beyond the clock allowance.
func PinRefreshDue(updatedAt, now time.Time) bool {
	age := now.Sub(updatedAt)
	return updatedAt.IsZero() || age >= PinRefreshInterval || age < -PinRefreshInterval
}

// ValidateFresh requires recent, complete inventories before pruning.
func (pins *ReleasePins) ValidateFresh(updatedAt, now time.Time) error {
	if err := pins.Validate(); err != nil {
		return err
	}
	age := now.Sub(updatedAt)
	if updatedAt.IsZero() || age > MaxPinAge || age < -PinRefreshInterval {
		return fmt.Errorf("%w: release pin inventory timestamp %s is missing, stale, or ahead of the clock", ErrInvalid, updatedAt)
	}
	return nil
}

type objectReader interface {
	GetObject(context.Context, objectstorage.GetObjectRequest) (objectstorage.GetObjectResponse, error)
}

// ReadObject joins SDK retry work while retaining cancellation at the HTTP boundary.
// Other implementations receive the original context and own their cancellation.
func ReadObject(ctx context.Context, client objectReader, request objectstorage.GetObjectRequest) (objectstorage.GetObjectResponse, error) {
	switch sdk := client.(type) {
	case objectstorage.ObjectStorageClient:
		ConfigureReadCancellation(&sdk.BaseClient)
		return sdk.GetObject(ReadContext(ctx), request)
	case *objectstorage.ObjectStorageClient:
		copy := *sdk
		ConfigureReadCancellation(&copy.BaseClient)
		return copy.GetObject(ReadContext(ctx), request)
	default:
		return client.GetObject(ctx, request)
	}
}

