func omitDeploymentFlags(args []string, flags ...string) []string {
	var kept []string
	for i := 0; i < len(args); i += 2 {
		if !slices.Contains(flags, args[i]) {
			kept = append(kept, args[i:i+2]...)
		}
	}
	return kept
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"time"

	"github.com/TerraScale/ts-orchestrator/internal/atlas"
	"github.com/TerraScale/ts-orchestrator/internal/releasechannel"
)

func discoverServingCells(ctx context.Context) ([]string, error) {
	return atlas.DiscoverServingCells(ctx, http.DefaultClient)
}

func deploymentCells(ctx context.Context, cells []string, discover func(context.Context) ([]string, error)) ([]string, error) {
	if len(cells) == 0 {
		if discover == nil {
			return nil, errors.New("serving-region discovery is unavailable")
		}
		var err error
		cells, err = discover(ctx)
		if err != nil {
			return nil, fmt.Errorf("discover serving regions: %w", err)
		}
	}
	if len(cells) == 0 {
		return nil, errors.New("serving-region discovery returned no regions")
	}
	seen := make(map[string]bool, len(cells))
	for _, cell := range cells {
		if !validRegion(cell) || seen[cell] {
			return nil, fmt.Errorf("unsupported or duplicate cell %q", cell)
		}
		seen[cell] = true
	}
	return cells, nil
}

func deploymentScope(ctx context.Context, location releasechannel.Location, cell string) (releasechannel.Status, error) {
	scope, found, err := releasechannel.ReadStatus(ctx, location)
	if err != nil {
		return scope, fmt.Errorf("read deployment scope: %w", err)
	}
	if !found {
		return scope, errors.New("regional deployment scope is missing; deploy its producer before the discovery consumer")
	}
	return scope, scope.ValidateDeploymentScope(cell, time.Now().UTC())
}

// ValidateDeploymentScope validates fresh regional inventory independently of
// release progress. A rolling or failed release still needs the next green build.
func (status Status) ValidateDeploymentScope(cell string, now time.Time) error {
	if status.Schema != StatusSchema || !release.ValidRegion(cell) || status.Cell != cell ||
		!release.ValidEnvironment(status.Environment) || len(status.Architectures) == 0 || len(status.Architectures) > 2 ||
		!slices.IsSorted(status.Architectures) {
		return fmt.Errorf("%w: missing or invalid deployment scope for %s", ErrInvalid, cell)
	}
	for i, architecture := range status.Architectures {
		if architecture != "amd64" && architecture != "arm64" || i > 0 && architecture == status.Architectures[i-1] {
			return fmt.Errorf("%w: unsupported or duplicate architecture for %s", ErrInvalid, cell)
		}
	}
	if status.UpdatedAt.IsZero() || now.Sub(status.UpdatedAt) > MaxPinAge || status.UpdatedAt.Sub(now) > PinRefreshInterval {
		return fmt.Errorf("%w: stale deployment scope for %s", ErrInvalid, cell)
	}
	return nil
}

