// serviceBucket is a region's head bucket whose leader admits the role's
// claim as a controller would, then reports outcome for it.
type serviceBucket struct {
	mu          sync.Mutex
	cell        string
	environment string
	signer      ed25519.PublicKey
	outcome     releasechannel.State
	objects     map[string][]byte
	log         *[]string
	logMu       *sync.Mutex
}

func (bucket *serviceBucket) PutObject(_ context.Context, request objectstorage.PutObjectRequest) (objectstorage.PutObjectResponse, error) {
	data, err := io.ReadAll(request.PutObjectBody)
	if err != nil {
		return objectstorage.PutObjectResponse{}, err
	}
	bucket.mu.Lock()
	defer bucket.mu.Unlock()
	name := *request.ObjectName
	if _, exists := bucket.objects[name]; exists && request.IfNoneMatch != nil {
		return objectstorage.PutObjectResponse{}, httpError(412)
	}
	bucket.objects[name] = data
	bucket.logMu.Lock()
	*bucket.log = append(*bucket.log, "put "+bucket.cell+" "+name)
	bucket.logMu.Unlock()
	return objectstorage.PutObjectResponse{}, nil
}

func (bucket *serviceBucket) GetObject(_ context.Context, request objectstorage.GetObjectRequest) (objectstorage.GetObjectResponse, error) {
	bucket.mu.Lock()
	defer bucket.mu.Unlock()
	name := *request.ObjectName
	data, ok := bucket.objects[name]
	if name == releasechannel.ServiceStatusObject("ts-auth") {
		data, ok = bucket.status()
	}
	if !ok {
		return objectstorage.GetObjectResponse{}, httpError(404)
	}
	sum := sha256.Sum256(data)
	return objectstorage.GetObjectResponse{Content: io.NopCloser(bytes.NewReader(data)), ETag: new(hex.EncodeToString(sum[:]))}, nil
}

// status fails a claim that does not verify for the bucket's cell, or whose
// binary is missing or differs.
func (bucket *serviceBucket) status() ([]byte, bool) {
	claim, ok := bucket.objects[releasechannel.ServiceReleaseObject("ts-auth")]
	if !ok {
		return nil, false
	}
	issued, _ := releasechannel.ClaimIssuedAt(claim)
	cell := strings.ToLower(bucket.cell)
	keyID, _ := protocol.KeyID(bucket.signer)
	codec := delivery.Ed25519Codec{Cell: cell, MaxLifetime: 5 * time.Minute, Trusted: map[string]delivery.TrustedSigner{
		keyID: {Actor: "ci-release", PublicKey: bucket.signer}}}
	status := releasechannel.ServiceStatus{Cell: bucket.cell, Role: "ts-auth", IssuedAt: issued, State: bucket.outcome}
	record, actor, err := codec.VerifyArchivedArtifact(context.Background(), claim)
	if err == nil {
		status.Digest = record.Digest
		binary := bucket.objects[releasechannel.ServiceBinaryObject("ts-auth", record.Digest)]
		sum := sha256.Sum256(binary)
		if actor != "ci-release" || record.Role != "ts-auth" || record.Environment != bucket.environment || hex.EncodeToString(sum[:]) != record.Digest || int64(len(binary)) != record.Size {
			err = errors.New("the binary is not the claimed one")
		}
	}
	if err != nil {
		status.State, status.Reason = releasechannel.StateFailed, err.Error()
	}
	encoded, _ := json.Marshal(status)
	return encoded, true
}

type serviceDeployFixture struct {
	binary, checkout, commit, key string
	buckets                       map[string]*serviceBucket
	log                           []string
	logMu                         sync.Mutex
	env                           deployEnv
}

func newServiceDeployFixture(t *testing.T) *serviceDeployFixture {
	t.Helper()
	directory := t.TempDir()
	fixture := &serviceDeployFixture{buckets: map[string]*serviceBucket{}, checkout: filepath.Join(directory, "source")}
	if err := os.Mkdir(fixture.checkout, 0o700); err != nil {
		t.Fatal(err)
	}
	writeFixtureFile(t, filepath.Join(fixture.checkout, "README"), []byte("ts-auth\n"), 0o644)
	for _, args := range [][]string{{"init", "-q"}, {"add", "README"},
		{"-c", "user.name=ci", "-c", "user.email=ci@example.com", "commit", "-q", "-m", "release"}} {
		if out, err := exec.Command("git", append([]string{"-C", fixture.checkout}, args...)...).CombinedOutput(); err != nil {
			t.Fatalf("git %v: %v\n%s", args, err, out)
		}
	}
	out, err := exec.Command("git", "-C", fixture.checkout, "rev-parse", "HEAD").Output()
	if err != nil {
		t.Fatal(err)
	}
	fixture.commit = strings.TrimSpace(string(out))
	fixture.binary = filepath.Join(directory, "ts-auth-linux-arm64")
	writeFixtureFile(t, fixture.binary, []byte("ts-auth release"), 0o755)
	public, private, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	fixture.key = filepath.Join(directory, "release.key")
	writePrivateKey(t, fixture.key, private)
	for _, cell := range []string{"GRU", "SFO"} {
		fixture.buckets[cell] = &serviceBucket{cell: cell, environment: "canary", signer: public, outcome: releasechannel.StateComplete,
			objects: map[string][]byte{}, log: &fixture.log, logMu: &fixture.logMu}
	}
	fixture.env = deployEnv{
		timeout:  2 * time.Second,
		discover: func(context.Context) ([]string, error) { return []string{"GRU", "SFO"}, nil },
		storage:  func(cell string) (releasechannel.ObjectClient, error) { return fixture.buckets[cell], nil },
		secret:   func(context.Context, string, string) ([]byte, error) { return nil, errors.New("no Vault in this test") },
	}
	return fixture
}

func (fixture *serviceDeployFixture) args(cells ...string) []string {
	args := []string{"--role", "ts-auth", "--binary", fixture.binary,
		"--repository", "https://github.com/TerraScale/ts-auth", "--commit", fixture.commit,
		"--source-checkout", fixture.checkout, "--environment", "canary", "--actor", "ci-release",
		"--signing-key", fixture.key, "--namespace", "ns", "--poll", "1ms"}
	for _, cell := range cells {
		args = append(args, "--cell", cell)
	}
	return args
}

package cli

import (
	"context"
	"crypto/ed25519"
	"encoding/hex"
	"errors"
	"flag"
	"fmt"
	"io"
	"strings"
	"time"

	"golang.org/x/sync/errgroup"

	"github.com/TerraScale/ts-orchestrator/internal/delivery"
	"github.com/TerraScale/ts-orchestrator/internal/release"
	"github.com/TerraScale/ts-orchestrator/internal/releasechannel"
	"github.com/TerraScale/ts-orchestrator/internal/rollout"
)

func (c command) serviceDeploy(args []string) error {
	return c.serviceDeployWith(args, deployEnv{storage: operatorObjectStorage, secret: readVaultSecret, discover: discoverServingCells})
}

// serviceDeployWith deploys one CI-built release of a native service role
// (TS-610) to every independent cell concurrently:
// for each cell it signs a delivery artifact claim with the role's scoped
// release key, uploads the binary to the cell's head bucket, publishes the
// claim in the role's release channel and waits until the cell's leader
// reports the role serving it. Failure does not interrupt another cell's
// healthy rollout; the command waits for every cell before returning.
func (c command) serviceDeployWith(args []string, env deployEnv) error {
	flags := flag.NewFlagSet("service-deploy", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	role := flags.String("role", "", "native service role, e.g. terrabase or ts-auth")
	binaryPath := flags.String("binary", "", "the release executable")
	repository := flags.String("repository", "", "HTTPS source repository the cells let the actor release")
	commit := flags.String("commit", "", "source commit SHA")
	checkout := flags.String("source-checkout", "", "checkout containing --commit, for the source tree digest")
	environment := flags.String("environment", "", "production or canary; default each region's admitted scope")
	actor := flags.String("actor", "", "a cell signer's actor; default the root-delegated release key's actor")
	keyPath := flags.String("signing-key", "", "owner-only Ed25519 PKCS#8 private key PEM of the release key")
	keySecret := flags.String("signing-key-secret", "", "OCI Vault secret holding the key, instead of --signing-key")
	vaultID := flags.String("vault-id", "", "OCI Vault of --signing-key-secret")
	namespace := flags.String("namespace", "", "Object Storage namespace of the regions' head buckets")
	poll := flags.Duration("poll", 5*time.Second, "how often a cell's status is read")
	var cells stringList
	flags.Var(&cells, "cell", "cell to deploy to concurrently; repeatable; default every serving cell")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *role == "" || *binaryPath == "" || *repository == "" || !release.ValidSourceRevision(*commit) || *checkout == "" ||
		*environment != "" && !validEnvironment(*environment) || (*keyPath == "") == (*keySecret == "") ||
		(*keySecret == "") != (*vaultID == "") || !validStorageToken(*namespace) ||
		*poll <= 0 || flags.NArg() != 0 {
		return errors.New("service-deploy requires --role, --binary, --repository, --commit, --source-checkout, --signing-key or --signing-key-secret with --vault-id and --namespace")
	}
	targetCells, err := deploymentCells(c.ctx, cells, env.discover)
	if err != nil {
		return err
	}
	cells = targetCells
	file, size, sum, err := c.openHashedArtifact(*binaryPath, releasechannel.MaxServiceBinaryBytes)
	if err != nil {
		return err
	}
	defer file.Close()
	digest := hex.EncodeToString(sum)
	tree, err := release.SourceTreeDigest(c.ctx, *checkout, *commit)
	if err != nil {
		return err
	}
	var private ed25519.PrivateKey
	if *keyPath != "" {
		private, err = readDelegatedPrivateKey(*keyPath)
	} else {
		var data []byte
		if data, err = env.secret(c.ctx, *vaultID, *keySecret); err == nil {
			private, err = parseDelegatedPrivateKey(data)
			clear(data)
		}
	}
	if err != nil {
		return fmt.Errorf("read the release key: %w", err)
	}
	defer clear(private)
	if *actor == "" {
		if *actor, err = release.DelegatedReleaseActor(private.Public().(ed25519.PublicKey)); err != nil {
			return err
		}
	}
	// The elapsed times measure CI green to rolled out (TS-623): the job
	// starts once the tests passed.
	regionTimeout := rollout.ObservationBudget
	if env.timeout > 0 {
		regionTimeout = min(regionTimeout, env.timeout)
	}
	started := time.Now()
	ctx, cancel := context.WithDeadline(c.ctx, started.Add(regionTimeout))
	defer cancel()
	c.ctx = ctx
	progress := &deploymentWriter{Writer: c.output}
	failures := make([]error, len(cells))
	var regions errgroup.Group
	for index, cell := range cells {
		regions.Go(func() (regionErr error) {
			defer func() {
				if regionErr != nil {
					failures[index] = fmt.Errorf("%s: %w", cell, regionErr)
					fmt.Fprintf(progress, "%s %s failed: %v\n", cell, *role, regionErr)
				}
			}()
			cellStarted := time.Now()
			location, err := channelLocation(env, cell, *namespace)
			if err != nil {
				return err
			}
			// The NATS cell is the lower-case logical cell.
			cellEnvironment := *environment
			if cellEnvironment == "" {
				scope, err := deploymentScope(c.ctx, location, cell)
				if err != nil {
					return err
				}
				cellEnvironment = scope.Environment
			}
			request := delivery.ArtifactClaimRequest{Source: delivery.ArtifactSource{Repository: *repository, Commit: *commit,
				TreeDigest: tree}, Cell: strings.ToLower(cell), Role: *role, Environment: cellEnvironment}
			record, err := delivery.NewArtifactRecord(request, digest, size)
			if err != nil {
				return err
			}
			// ReadAt keeps parallel uploads on the inspected inode with independent offsets.
			if err := putImmutable(c.ctx, location.Client, location.Namespace, location.Bucket,
				releasechannel.ServiceBinaryObject(*role, digest), io.NewSectionReader(file, 0, size), size, sum); err != nil {
				return fmt.Errorf("upload the binary to %s: %w", cell, err)
			}
			// Every cell shares the deployment's signed observation start.
			codec := delivery.Ed25519Codec{Cell: request.Cell, Actor: *actor, PrivateKey: private, Lifetime: time.Minute,
				MaxLifetime: 5 * time.Minute, Now: func() time.Time { return started.UTC() }}
			claim, err := codec.SignArtifact(c.ctx, record)
			if err != nil {
				return fmt.Errorf("sign the %s claim: %w", cell, err)
			}
			issued, err := releasechannel.ClaimIssuedAt(claim)
			if err != nil {
				return err
			}
			if err := releasechannel.PublishService(c.ctx, location, *role, claim); err != nil {
				return fmt.Errorf("publish to %s: %w", cell, err)
			}
			fmt.Fprintf(progress, "%s %s published: %s %s\n", cell, *role, digest, *commit)
			if err := releasechannel.AwaitService(c.ctx, location, cell, *role, digest, issued, *poll,
				started.Add(regionTimeout), progress); err != nil {
				return err
			}
			fmt.Fprintf(progress, "%s %s rolled out in %s\n", cell, *role, time.Since(cellStarted).Round(time.Second))
			return nil
		})
	}
	_ = regions.Wait()
	if err := errors.Join(failures...); err != nil {
		return fmt.Errorf("service rollout failed after %s: %w", time.Since(started).Round(time.Second), err)
	}
	_, err = fmt.Fprintf(c.output, "%s complete: %s %s in %s after %s\n", *role, digest, *commit, strings.Join(cells, " "),
		time.Since(started).Round(time.Second))
	return err
}

// SourceTreeDigest is the SHA-256 of `git archive` of commit in checkout:
// the source claim of a native service release (TerraBase, ts-auth), whose
// releases publish none. The operator's release commands and CI's
// service-deploy compute it the same way, whatever the local Git settings.
func SourceTreeDigest(ctx context.Context, checkout, commit string) (string, error) {
	if !ValidSourceRevision(commit) {
		return "", errors.New("--commit must be a full lowercase commit SHA")
	}
	// Archive from an empty repository that borrows the checkout's objects,
	// so no attributes from outside the commit (info/attributes,
	// core.attributesFile, the system file) apply, and pin the file modes.
	// No inherited GIT_* variable reaches git.
	env := []string{"GIT_ATTR_NOSYSTEM=1"}
	for _, variable := range os.Environ() {
		if !strings.HasPrefix(variable, "GIT_") {
			env = append(env, variable)
		}
	}
	git := func(args ...string) *exec.Cmd {
		command := exec.CommandContext(ctx, "git", args...)
		command.Env = env
		return command
	}
	objects, err := git("-C", checkout, "rev-parse", "--path-format=absolute", "--git-path", "objects").Output()
	if err != nil {
		return "", fmt.Errorf("find the objects of %s: %w", checkout, err)
	}
	isolated, err := os.MkdirTemp("", "ts-source-tree-")
	if err != nil {
		return "", err
	}
	defer os.RemoveAll(isolated)
	// The empty repository and its archive read no system or global
	// config (an init.templateDir could bring info/attributes) and no
	// template; reading the checkout may still need the user's safe.directory.
	isolate := func(command *exec.Cmd) *exec.Cmd {
		command.Env = append(command.Env, "GIT_CONFIG_NOSYSTEM=1", "GIT_CONFIG_GLOBAL=/dev/null")
		return command
	}
	if out, err := isolate(git("init", "-q", "--bare", "--template=", isolated)).CombinedOutput(); err != nil {
		return "", fmt.Errorf("prepare the source archive: %w: %s", err, out)
	}
	command := isolate(git("--git-dir", isolated, "-c", "tar.umask=0002", "-c", "core.attributesFile=/dev/null",
		"archive", "--format=tar", commit+"^{commit}"))
	command.Env = append(command.Env, "GIT_ALTERNATE_OBJECT_DIRECTORIES="+strings.TrimSpace(string(objects)))
	stdout, err := command.StdoutPipe()
	if err != nil {
		return "", err
	}
	if err := command.Start(); err != nil {
		return "", err
	}
	hash := sha256.New()
	_, copyErr := io.Copy(hash, stdout)
	if err := errors.Join(copyErr, command.Wait()); err != nil {
		return "", fmt.Errorf("archive source %s: %w", commit, err)
	}
	return hex.EncodeToString(hash.Sum(nil)), nil
}

func publishService(ctx context.Context, location Location, role string, claim []byte, migration *release.SequenceMigration, roots trust.Keyring) error {
	record, issued, err := serviceClaimOrder(claim)
	if err != nil {
		return err
	}
	name := ServiceReleaseObject(role)
	for range 3 {
		current, etag, found, err := location.get(ctx, name, MaxServiceClaimBytes)
		if err != nil {
			return err
		}
		if found {
			existing, existingIssued, err := serviceClaimOrder(current)
			if err != nil {
				return fmt.Errorf("decode current service release: %w", err)
			}
			switch {
			case existing.ReleaseSequence > 0:
				if record.ReleaseSequence > 0 {
					envelope, found, err := ReadSequenceMigration(ctx, location, existing.SequenceMigrationSHA256)
					if err != nil {
						return err
					}
					if !found {
						return fmt.Errorf("%w: existing migration missing", ErrInvalid)
					}
					existingMigration, err := release.VerifySequenceMigrationHistorical(envelope, roots, role, existing.Environment)
					if err != nil {
						return err
					}
					if err := verifyServiceSequenceClaim(ctx, current, existingMigration); err != nil {
						return err
					}
				}
				if record.ReleaseSequence < existing.ReleaseSequence {
					return ErrStale
				}
				if record.ReleaseSequence == existing.ReleaseSequence {
					incomingContent, err := record.ContentManifestDigest()
					if err != nil {
						return err
					}
					retainedContent, err := existing.ContentManifestDigest()
					if err != nil {
						return err
					}
					if incomingContent != retainedContent || record.SequenceMigrationSHA256 != existing.SequenceMigrationSHA256 {
						return fmt.Errorf("%w: sequence already names another artifact", ErrInvalid)
					}
				}
			case record.ReleaseSequence > 0:
				if migration == nil || !migration.AdmitsLegacyFloor(strings.ToUpper(record.Cell), 0, existingIssued) {
					return fmt.Errorf("%w: migration does not cover retained service floor", ErrStale)
				}
			case existingIssued.After(time.Now().Add(ClaimClockSkew)):
			case existingIssued.After(issued):
				return ErrStale
			case existingIssued.Equal(issued) && !bytes.Equal(current, claim):
				return fmt.Errorf("%w: another release shares issuance instant", ErrInvalid)
			}
		}
		if err := location.put(ctx, name, claim, etag); !errors.Is(err, ErrConflict) {
			return err
		}
	}
	return ErrConflict
}

// ReadServiceClaim returns role's release.json; found is false when the
// role has none.
func ReadServiceClaim(ctx context.Context, location Location, role string) ([]byte, bool, error) {
	data, _, found, err := location.get(ctx, ServiceReleaseObject(role), MaxServiceClaimBytes)
	return data, found, err
}

// ReadServiceStatus returns role's status; found is false when it has none.
func ReadServiceStatus(ctx context.Context, location Location, role string) (ServiceStatus, bool, error) {
	var status ServiceStatus
	found, err := location.read(ctx, ServiceStatusObject(role), maxStatusBytes, &status)
	return status, found, err
}

// AwaitService polls role's status every poll until it reports the release
// with digest issued at issued complete. It fails when the region reports it
// failed or a newer release replaced it, or when deadline passes. Each status
// change is written to progress.
func AwaitService(ctx context.Context, location Location, cell, role, digest string, issued time.Time,
	poll time.Duration, deadline time.Time, progress io.Writer,
) error {
	return awaitService(ctx, location, cell, role, digest, issued, 0, poll, deadline, progress)
}

func AwaitServiceSequenced(ctx context.Context, location Location, cell, role, digest string, issued time.Time, sequence uint64, poll time.Duration, deadline time.Time, progress io.Writer) error {
	if sequence == 0 {
		return fmt.Errorf("%w: missing service sequence", ErrInvalid)
	}
	return awaitService(ctx, location, cell, role, digest, issued, sequence, poll, deadline, progress)
}

func awaitService(ctx context.Context, location Location, cell, role, digest string, issued time.Time, sequence uint64, poll time.Duration, deadline time.Time, progress io.Writer) error {
	// The deadline also bounds a stalled read.
	ctx, cancel := context.WithDeadline(ctx, deadline)
	defer cancel()
	var last string
	for {
		status, found, err := ReadServiceStatus(ctx, location, role)
		line := "waiting for the region to report"
		switch {
		case err != nil:
			line = "status read failed: " + err.Error()
		case !found || sequence > 0 && status.ReleaseSequence < sequence || sequence == 0 && status.ReleaseSequence == 0 && status.IssuedAt.Before(issued):
		case status.ReleaseSequence > sequence || sequence == 0 && status.IssuedAt.After(issued):
			return fmt.Errorf("%w: %s moved on to a %s release issued at %s", ErrFailed, cell, role, status.IssuedAt)
		case status.State == StateFailed && status.Cell == cell && (status.Digest == "" || status.Digest == digest):
			return fmt.Errorf("%w: %s did not release %s %s: %s", ErrFailed, cell, role, digest, Clip(status.Reason))
		case status.Digest == "" && status.State == StateRolling:
			// A leader that has not decoded the claim yet names no digest.
			line = Clip(string(status.State) + " " + status.Reason)
		case status.Cell != cell || status.Role != role || status.Digest != digest:
			return fmt.Errorf("%w: %s reports %s %s for %s", ErrFailed, cell, Clip(status.Role), Clip(status.Digest), Clip(status.Cell))
		case status.State == StateComplete:
			fmt.Fprintf(progress, "%s %s complete: %s\n", cell, role, digest)
			return nil
		default:
			line = Clip(string(status.State) + " " + status.Reason)
		}
		if line != last {
			fmt.Fprintf(progress, "%s %s %s\n", cell, role, line)
			last = line
		}
		if !time.Now().Before(deadline) {
			return fmt.Errorf("%w: %s did not complete %s %s in time (%s)", ErrFailed, cell, role, digest, line)
		}
		select {
		case <-ctx.Done():
			if !time.Now().Before(deadline) {
				return fmt.Errorf("%w: %s did not complete %s %s in time (%s)", ErrFailed, cell, role, digest, line)
			}
			return ctx.Err()
		case <-time.After(min(poll, time.Until(deadline))):
		}
	}
}

