func (f *applyHTTPFixture) serve(w http.ResponseWriter, r *http.Request) {
	parts := strings.SplitN(r.URL.Path, "/", 7)
	if len(parts) != 7 || parts[1] != "n" || parts[3] != "b" || parts[5] != "o" || r.Header.Get("Authorization") == "" {
		http.Error(w, "invalid OCI request", http.StatusBadRequest)
		return
	}
	cell, _, _ := strings.Cut(strings.ToUpper(parts[4]), "-")
	name := parts[6]
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.objects[cell] == nil {
		f.objects[cell] = make(map[string][]byte)
	}
	if cell == "SFO" && f.failure == "unreachable" && name == releasechannel.StatusObject {
		f.mu.Unlock()
		<-r.Context().Done()
		f.mu.Lock()
		return
	}
	if cell == "SFO" && f.failure == "storage" && r.Method == http.MethodPut {
		http.Error(w, "unavailable", http.StatusForbidden)
		return
	}
	if r.Method == http.MethodPut {
		old, exists := f.objects[cell][name]
		if r.Header.Get("If-None-Match") == "*" && exists || r.Header.Get("If-Match") != "" && r.Header.Get("If-Match") != fmt.Sprintf("%x", len(old)) {
			w.WriteHeader(http.StatusPreconditionFailed)
			return
		}
		data, err := io.ReadAll(r.Body)
		if err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}
		f.objects[cell][name] = data
		if name == releasechannel.ChannelObject {
			f.channelWrites[cell]++
		} else {
			f.binaryCreates[cell]++
		}
		w.Header().Set("etag", fmt.Sprintf("%x", len(data)))
		return
	}
	data, exists := f.objects[cell][name]
	if name == releasechannel.StatusObject {
		status := releasechannel.Status{Schema: releasechannel.StatusSchema, Cell: cell, Environment: "production",
			Architectures: []string{"amd64"}, UpdatedAt: time.Now().UTC()}
		if cell == "SFO" {
			switch f.failure {
			case "missing":
				w.WriteHeader(http.StatusNotFound)
				return
			case "stale":
				status.UpdatedAt = status.UpdatedAt.Add(-time.Hour)
			case "environment":
				status.Environment = "canary"
			case "architecture":
				status.Architectures = []string{"arm64"}
			}
		}
		if wire, ok := f.objects[cell][releasechannel.ChannelObject]; ok {
			var channel releasechannel.Channel
			if err := json.Unmarshal(wire, &channel); err == nil {
				_, err := channel.Verify(f.roots, cell, "production", time.Now().UTC())
				status.SourceRevision, status.RunNumber = channel.SourceRevision, channel.RunNumber
				status.State = releasechannel.StateComplete
				if err != nil {
					status.State, status.Reason = releasechannel.StateFailed, err.Error()
				}
			}
		}
		data, _ = json.Marshal(status)
		exists = true
	}
	if !exists {
		w.WriteHeader(http.StatusNotFound)
		return
	}
	w.Header().Set("etag", fmt.Sprintf("%x", len(data)))
	w.Header().Set("Content-Type", "application/json")
	_, _ = w.Write(data)
}

func applyFixtureCommand(t *testing.T, dir, program string, args ...string) string {
	t.Helper()
	name := program
	if os.Getenv("CI") != "true" {
		name, args = "nice", append([]string{"-n", "19", program}, args...)
	}
	command := exec.CommandContext(t.Context(), name, args...)
	command.Dir = dir
	command.Env = append(os.Environ(), "CGO_ENABLED=0", "GOOS=linux", "GOARCH=amd64")
	output, err := command.CombinedOutput()
	if err != nil {
		t.Fatalf("%s: %v\n%s", program, err, output)
	}
	return string(output)
}

type applyFixtureLineage struct {
	t   *testing.T
	dir string
}

func (l applyFixtureLineage) CheckLineage(base, revision, ref string) error {
	applyFixtureCommand(l.t, l.dir, "git", "merge-base", "--is-ancestor", base, revision)
	applyFixtureCommand(l.t, l.dir, "git", "merge-base", "--is-ancestor", revision, ref)
	return nil
}

// OCI SDK endpoint selection runs per operation; force all fixture traffic local.
type applyHTTPDispatcher struct{ server *httptest.Server }

func (d applyHTTPDispatcher) Do(request *http.Request) (*http.Response, error) {
	local, err := url.Parse(d.server.URL)
	if err != nil {
		return nil, err
	}
	request = request.Clone(request.Context())
	request.URL = request.URL.Clone()
	request.URL.Scheme, request.URL.Host = local.Scheme, local.Host
	request.Host = local.Host
	return d.server.Client().Do(request)
}

func productionCandidate(binary binaryReceipt, cell string) release.ProductionExpectation {
	return release.ProductionExpectation{SourceRevision: binary.SourceRevision, ArtifactSHA256: binary.SHA256,
		QualificationSHA256: binary.QualificationSHA256, Cell: cell, Environment: "production",
		Runtime: release.ProductionRuntime, Architecture: binary.GOARCH, Role: "orchestrator"}
}

func writeProductionEvidence(t *testing.T, directory string, candidate release.ProductionExpectation) release.ProductionQualification {
	t.Helper()
	if err := os.MkdirAll(filepath.Join(directory, "objects"), 0o700); err != nil {
		t.Fatal(err)
	}
	record := release.ProductionQualification{Schema: release.ProductionQualificationSchema, Candidate: candidate}
	for _, gate := range []string{"runtime-ha", "workload-safety"} {
		data, err := json.Marshal(struct{ Gate, SourceRevision, ArtifactSHA256 string }{gate, candidate.SourceRevision, candidate.ArtifactSHA256})
		if err != nil {
			t.Fatal(err)
		}
		digest := sha256.Sum256(data)
		sum := hex.EncodeToString(digest[:])
		if err := os.WriteFile(filepath.Join(directory, "objects", sum), data, 0o600); err != nil {
			t.Fatal(err)
		}
		record.Evidence = append(record.Evidence, release.ProductionGateEvidence{Gate: gate, SHA256: sum,
			Bytes: int64(len(data)), CompletedAt: time.Now().UTC().Add(-3 * time.Hour)})
	}
	return record
}

func writeProductionRecord(t *testing.T, path string, record release.ProductionQualification, private ed25519.PrivateKey, issued, expires time.Time) {
	t.Helper()
	payload, err := trust.EncodePayload(record)
	if err != nil {
		t.Fatal(err)
	}
	envelope, err := trust.Sign(payload, release.ProductionQualificationScope(record.Candidate), issued, expires, private)
	if err != nil {
		t.Fatal(err)
	}
	wire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, wire, 0o600); err != nil {
		t.Fatal(err)
	}
}

func writeQualificationDelegation(t *testing.T, path string, candidate release.ProductionExpectation, private, root ed25519.PrivateKey, domain string) {
	t.Helper()
	public := private.Public().(ed25519.PublicKey)
	keyID, _ := trust.KeyID(public)
	encoded, _ := trust.EncodeDelegatedPublicKey(public)
	scope := release.ProductionQualificationScope(candidate)
	delegation, err := trust.SignDelegation(trust.Delegation{SchemaVersion: trust.SchemaVersion, SubjectKeyID: keyID, SubjectPublicKey: encoded,
		Capabilities: []trust.Capability{{Domain: domain, DeploymentID: scope.DeploymentID, Cell: scope.Cell,
			Environment: scope.Environment, Role: scope.Role, Slots: []string{scope.Slot}, Actions: []string{"sign"}}}},
		time.Now().Add(-time.Hour), time.Now().Add(2*time.Hour), root)
	if err != nil {
		t.Fatal(err)
	}
	wire, _ := trust.EncodeEnvelope(delegation)
	if err := os.WriteFile(path, wire, 0o600); err != nil {
		t.Fatal(err)
	}
}

