func signBinaryWithCheck(args []string, check func(release.Qualification, string) error,
	inspect func(string, string, string) (binaryReceipt, error),
) error {
	return (command{ctx: context.Background(), output: os.Stdout}).signBinaryWithCheck(args, check, inspect)
}

func (c command) signBinary(args []string) error {
	return c.signBinaryWithCheck(args, c.verifyGitHubQualification, c.inspectBinary)
}

func (c command) signBinaryWithCheck(args []string, check func(release.Qualification, string) error,
	inspect func(string, string, string) (binaryReceipt, error),
) error {
	flags := flag.NewFlagSet("sign-binary", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	candidate := flags.String("candidate", "", "unsigned canonical binary receipt")
	binaryPath := flags.String("binary", "", "retained CI binary matching the candidate")
	qualificationPath := flags.String("qualification", "", "retained CI qualification manifest")
	delegationPath := flags.String("delegation", "", "root-signed release delegation envelope")
	rootPath := flags.String("root-key", "", "baked root public key PEM")
	privatePath := flags.String("signing-key", "", "delegated Ed25519 PKCS#8 private key PEM")
	environment := flags.String("environment", "", "production or canary")
	validFor := flags.Duration("valid-for", defaultValidFor, "receipt validity, bounded by delegation expiry")
	output := flags.String("out", "", "new signed envelope path")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *candidate == "" || *binaryPath == "" || *qualificationPath == "" || *delegationPath == "" || *rootPath == "" || *privatePath == "" || !validEnvironment(*environment) || *output == "" || flags.NArg() != 0 {
		return errors.New("sign-binary requires --candidate, --binary, --qualification, --delegation, --root-key, --signing-key, --environment, and --out")
	}
	payload, err := readCanonicalPayload[binaryReceipt](*candidate)
	if err != nil {
		return err
	}
	if err := validateBinaryReceipt(payload); err != nil {
		return err
	}
	qualification, qualificationDigest, err := readQualification(*qualificationPath)
	if err != nil {
		return err
	}
	if err := qualification.MatchBinary(payload, qualificationDigest); err != nil {
		return err
	}
	observed, err := inspect(*binaryPath, payload.GoVersion, payload.SourceRevision)
	if err != nil {
		return err
	}
	if err := c.ctx.Err(); err != nil {
		return err
	}
	observed.QualificationSHA256 = qualificationDigest
	if observed != payload {
		return errors.New("retained CI binary does not match the qualified candidate")
	}
	if err := check(qualification, qualificationDigest); err != nil {
		return err
	}
	envelope, err := c.signReceiptWithFiles(payload, *environment, *delegationPath, *rootPath, *privatePath, *validFor)
	if err != nil {
		return err
	}
	encoded, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		return err
	}
	return c.writeNew(*output, encoded, 0o644)
}

func (c command) signReceiptWithFiles(payload any, environment, delegationPath, rootPath, privatePath string,
	validFor time.Duration,
) (trust.Envelope, error) {
	if err := c.ctx.Err(); err != nil {
		return trust.Envelope{}, err
	}
	delegation, err := readEnvelope(delegationPath)
	if err != nil {
		return trust.Envelope{}, err
	}
	root, err := readRootPublicKey(rootPath)
	if err != nil {
		return trust.Envelope{}, err
	}
	roots, err := trust.ParseKeyring(root)
	if err != nil {
		return trust.Envelope{}, err
	}
	private, err := readDelegatedPrivateKey(privatePath)
	if err != nil {
		return trust.Envelope{}, err
	}
	defer clear(private)
	if err := c.ctx.Err(); err != nil {
		return trust.Envelope{}, err
	}
	now := time.Now().UTC()
	switch receipt := payload.(type) {
	case binaryReceipt:
		return release.SignBinaryReceipt(receipt, environment, delegation, roots, private, now, validFor)
	case imageReceipt:
		return release.SignImageReceipt(receipt, environment, delegation, roots, private, now, validFor)
	default:
		return trust.Envelope{}, fmt.Errorf("unsupported release receipt type %T", payload)
	}
}

func verifyBinaryReceiptFiles(envelopePath, delegationPath, rootPath, environment string) (release.VerifiedBinary, error) {
	envelopeWire, delegationWire, roots, err := readReceiptVerificationInputs(envelopePath, delegationPath, rootPath)
	if err != nil {
		return release.VerifiedBinary{}, err
	}
	return release.VerifyBinaryCurrent(envelopeWire, delegationWire, roots,
		release.BinaryExpectation{Environment: environment}, time.Now().UTC())
}

func (c command) writeNew(path string, contents []byte, mode os.FileMode) error {
	if err := c.ctx.Err(); err != nil {
		return err
	}
	if path == "" || len(contents) == 0 {
		return errors.New("output path and content are required")
	}
	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, mode)
	if err != nil {
		return fmt.Errorf("create output without overwrite: %w", err)
	}
	if _, err := file.Write(contents); err != nil {
		file.Close()
		os.Remove(path)
		return err
	}
	if err := file.Sync(); err != nil {
		file.Close()
		os.Remove(path)
		return err
	}
	if err := c.ctx.Err(); err != nil {
		file.Close()
		os.Remove(path)
		return err
	}
	if err := file.Close(); err != nil {
		os.Remove(path)
		return err
	}
	return nil
}

func DecodeQualification(wire []byte) (Qualification, string, error) {
	var qualification Qualification
	if err := protocol.DecodeStrict(wire, &qualification, MaxQualificationBytes); err != nil {
		return Qualification{}, "", fmt.Errorf("decode qualification: %w", err)
	}
	if err := qualification.Validate(); err != nil {
		return Qualification{}, "", err
	}
	digest := sha256.Sum256(wire)
	return qualification, hex.EncodeToString(digest[:]), nil
}

func (qualification Qualification) Validate() error {
	if qualification.Schema != QualificationSchema || qualification.Repository != QualificationRepository ||
		!revisionPattern.MatchString(qualification.SourceRevision) || !revisionPattern.MatchString(qualification.SourceTree) ||
		qualification.GoVersion != DefaultGoVersion || !digestPattern.MatchString(qualification.GoModSHA256) ||
		!digestPattern.MatchString(qualification.GoSumSHA256) ||
		qualification.Verification.Workflow != QualificationWorkflow || qualification.Verification.Job != QualificationJob ||
		qualification.Verification.RunID <= 0 || qualification.Verification.RunNumber <= 0 ||
		qualification.Verification.Conclusion != "success" {
		return fmt.Errorf("%w: source or required successful check", ErrInvalidQualification)
	}
	if len(qualification.Artifacts) != 2 {
		return fmt.Errorf("%w: both Linux architectures are required", ErrInvalidQualification)
	}
	for index, architecture := range [...]string{"amd64", "arm64"} {
		asset := qualification.Artifacts[index]
		if asset.Architecture != architecture || asset.Name != "terrascale-orchestrator-linux-"+architecture ||
			asset.Bytes <= 0 || asset.Bytes > MaxArtifactBytes || !digestPattern.MatchString(asset.SHA256) {
			return fmt.Errorf("%w: invalid or unordered %s artifact", ErrInvalidQualification, architecture)
		}
	}
	return nil
}

// MatchBinary binds a v2 signed receipt to the exact qualification manifest
// and the retained artifact metadata for its architecture.
func (qualification Qualification) MatchBinary(receipt BinaryReceipt, qualificationSHA256 string) error {
	if err := qualification.Validate(); err != nil {
		return err
	}
	if err := receipt.Validate(); err != nil {
		return err
	}
	if receipt.SourceRevision != qualification.SourceRevision || receipt.GoVersion != qualification.GoVersion ||
		receipt.QualificationSHA256 != qualificationSHA256 {
		return fmt.Errorf("%w: binary source or manifest digest mismatch", ErrInvalidQualification)
	}
	for _, asset := range qualification.Artifacts {
		if asset.Architecture == receipt.GOARCH {
			if asset.Bytes != receipt.Bytes || asset.SHA256 != receipt.SHA256 {
				return fmt.Errorf("%w: binary differs from retained artifact", ErrInvalidQualification)
			}
			return nil
		}
	}
	return fmt.Errorf("%w: binary architecture is missing", ErrInvalidQualification)
}

// SignBinaryReceipt verifies a current root delegation, applies the release
// signing lifetime limits, signs the canonical payload, and re-verifies the
// result through the consumer policy before returning it.
func SignBinaryReceipt(receipt BinaryReceipt, environment string, delegation trust.Envelope, roots trust.Keyring,
	privateKey ed25519.PrivateKey, now time.Time, validFor time.Duration,
) (trust.Envelope, error) {
	if err := receipt.Validate(); err != nil {
		return trust.Envelope{}, err
	}
	if err := validateEnvironment(environment); err != nil {
		return trust.Envelope{}, err
	}
	return signReceipt(receipt, BinaryScope(receipt, environment), delegation, roots, privateKey, now, validFor)
}

func signReceipt(payload any, scope trust.Scope, delegationEnvelope trust.Envelope, roots trust.Keyring,
	privateKey ed25519.PrivateKey, now time.Time, validFor time.Duration,
) (trust.Envelope, error) {
	if validFor <= 0 || validFor > MaxReceiptLifetime {
		return trust.Envelope{}, fmt.Errorf("receipt validity must be positive and no longer than %s", MaxReceiptLifetime)
	}
	delegation, err := trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, delegationPolicy())
	if err != nil {
		return trust.Envelope{}, fmt.Errorf("verify current release delegation: %w", err)
	}
	expiresAt := now.Add(validFor)
	if delegationEnvelope.ExpiresAt.Before(expiresAt) {
		expiresAt = delegationEnvelope.ExpiresAt
	}
	if !expiresAt.After(now) {
		return trust.Envelope{}, trust.ErrExpired
	}
	encodedPayload, err := trust.EncodePayload(payload)
	if err != nil {
		return trust.Envelope{}, err
	}
	envelope, err := trust.Sign(encodedPayload, scope, now, expiresAt, privateKey)
	if err != nil {
		return trust.Envelope{}, err
	}
	if _, err := trust.VerifyDelegatedCurrent(envelope, scope, delegation, now, receiptPolicy()); err != nil {
		return trust.Envelope{}, fmt.Errorf("release signer is not delegated for this exact scope: %w", err)
	}
	return envelope, nil
}
